// components/home/Home.js
import React from "react";
import { useSelector } from "react-redux";

const Home = () => {
  const username = useSelector((state) => state.auth.username);
  const roles = useSelector((state) => state.auth.roles || []);

  return (
    <div className="container mt-5">
      <div className="card shadow">
        <div className="card-body text-center">
          <h3 className="card-title mb-4">Welcome, {username}!</h3>
          <p className="lead">You are logged in as a regular user.</p>

          <div className="mt-4">
            <h5>Your Roles:</h5>
            <div className="d-flex justify-content-center gap-2 mt-2">
              {roles.map((role, index) => (
                <span key={index} className="badge bg-primary">
                  {role.replace("ROLE_", "")}
                </span>
              ))}
            </div>
          </div>

          <div className="mt-5">
            <div className="alert alert-info">
              <h6>User Permissions:</h6>
              <ul className="text-start">
                <li>Can view their own profile</li>
                <li>Can update their information</li>
                <li>Cannot access admin panel</li>
                <li>Cannot add/edit other users</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
